    # /v1/fga
    module FgaOperations
      # Validate an authorization model and convert it: DSL (or modular DSL files) to canonical JSON, and JSON to DSL.
      # `POST /v1/fga/models/transform` (scope: fga:read)
      # @return [Hash]
      def transform_model(dsl: UNSET, modules: UNSET, model: UNSET, idempotency_key: nil)
        body = G.compact("dsl" => dsl, "modules" => modules, "model" => model)
        request(method: :post, path: "/v1/fga/models/transform", body: body, idempotency_key: idempotency_key)
      end

      # How this instance runs fine-grained authorization reads: the result-cache TTL, the consistency mode applied to reads that name none, and how long the tuple change log is kept.
      # `GET /v1/fga/settings` (scope: fga:read)
      # @return [Atlas::Models::FgaSettings]
      def get_settings()
        G.wrap(M::FgaSettings, request(method: :get, path: "/v1/fga/settings"))
      end

      # Change the instance FGA settings. Fields you omit keep their value. `cache_ttl_ms` null uses the platform default and 0 turns the result cache off; a request that carries its own `consistency` always wins over `default_consistency`; `changelog_retention_days` null keeps the whole tuple change log, otherwise older changes are removed in the background.
      # `PUT /v1/fga/settings` (scope: fga:write)
      # @return [Atlas::Models::FgaSettings]
      def set_settings(cache_ttl_ms: UNSET, default_consistency: UNSET, changelog_retention_days: UNSET, idempotency_key: nil)
        body = G.compact("cache_ttl_ms" => cache_ttl_ms, "default_consistency" => default_consistency, "changelog_retention_days" => changelog_retention_days)
        G.wrap(M::FgaSettings, request(method: :put, path: "/v1/fga/settings", body: body, idempotency_key: idempotency_key))
      end

      # Run the stored assertions of a model version against the real store tuples.
      # `POST /v1/fga/stores/{id}/authorization-models/{mid}/assertions/run` (scope: fga:read)
      # @return [Hash]
      def run_assertion(id, mid, idempotency_key: nil)
        request(method: :post, path: "/v1/fga/stores/#{enc(id)}/authorization-models/#{enc(mid)}/assertions/run", idempotency_key: idempotency_key)
      end

      # What changed between a model version and the one before it (or `against`): types, relations, conditions, and whether the change can alter who has access.
      # `GET /v1/fga/stores/{id}/authorization-models/{mid}/diff` (scope: fga:read)
      # @return [Hash]
      def get_diff(id, mid, against: UNSET)
        query = G.compact("against" => against)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/authorization-models/#{enc(mid)}/diff", query: query)
      end

      # The nodes and edges of an authorization model, for a visualizer.
      # `GET /v1/fga/stores/{id}/authorization-models/{mid}/graph` (scope: fga:read)
      # @return [Hash]
      def get_graph(id, mid)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/authorization-models/#{enc(mid)}/graph")
      end

      # Export the store tuples as NDJSON (one tuple per line), paged: pass the `atlas-next-cursor` response header back as `cursor`.
      # `GET /v1/fga/stores/{id}/export` (scope: fga:read)
      # @return [Hash]
      def get_export(id, cursor: UNSET, limit: UNSET)
        query = G.compact("cursor" => cursor, "limit" => limit)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/export", query: query)
      end

      # Bulk-import up to 20,000 tuples. Idempotent: an existing tuple is untouched, a changed condition or expiry updates it. Validated against the latest model; `dry_run` reports how many are new without writing.
      # `POST /v1/fga/stores/{id}/import` (scope: fga:write)
      # @return [Hash]
      def import_store(id, tuples: UNSET, dry_run: UNSET, idempotency_key: nil)
        body = G.compact("tuples" => tuples, "dry_run" => dry_run)
        request(method: :post, path: "/v1/fga/stores/#{enc(id)}/import", body: body, idempotency_key: idempotency_key)
      end

      # The materialized permission sets of a store: which (object type, relation, user type) answers are precomputed, their status, the revision they were built at and when a tuple expiry will next invalidate them.
      # `GET /v1/fga/stores/{id}/materializations` (scope: fga:read)
      # @return [Hash]
      def get_materializations(id)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/materializations")
      end

      # Precompute list-objects for every user of `user_type` on `object_type#relation`, so a huge list question is one indexed read. The first build runs now; the worker rebuilds after tuple writes. A stored answer is served only while it is current for the store revision and model, before any tuple expiry, and for a plain `type:id` user with no request context or contextual tuples; otherwise list-objects is answered live. A model that uses conditions cannot be materialized.
      # `POST /v1/fga/stores/{id}/materializations` (scope: fga:write)
      # @return [Hash]
      def create_materialization(id, object_type: UNSET, relation: UNSET, user_type: UNSET, idempotency_key: nil)
        body = G.compact("object_type" => object_type, "relation" => relation, "user_type" => user_type)
        request(method: :post, path: "/v1/fga/stores/#{enc(id)}/materializations", body: body, idempotency_key: idempotency_key)
      end

      # Remove a materialization; list-objects is then always computed live.
      # `DELETE /v1/fga/stores/{id}/materializations/{mid}` (scope: fga:write)
      # @return [Hash]
      def delete_materialization(id, mid, idempotency_key: nil)
        request(method: :delete, path: "/v1/fga/stores/#{enc(id)}/materializations/#{enc(mid)}", idempotency_key: idempotency_key)
      end

      # Rebuild one materialization now.
      # `POST /v1/fga/stores/{id}/materializations/{mid}/rebuild` (scope: fga:write)
      # @return [Hash]
      def rebuild_materialization(id, mid, idempotency_key: nil)
        request(method: :post, path: "/v1/fga/stores/#{enc(id)}/materializations/#{enc(mid)}/rebuild", idempotency_key: idempotency_key)
      end

      # What a local policy decision point syncs: the latest model and the store tuples. Without `since`, a page of tuples (`full: true`, follow `next_cursor`); with `since=<revision>`, only the tuple changes after that revision. Tuples carry `expires_at`; expired tuples are never listed.
      # `GET /v1/fga/stores/{id}/snapshot` (scope: fga:read)
      # @return [Hash]
      def get_snapshot(id, since: UNSET, cursor: UNSET, limit: UNSET)
        query = G.compact("since" => since, "cursor" => cursor, "limit" => limit)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/snapshot", query: query)
      end

      # Run an FGA test suite in memory: a model (DSL, modules, a version id or the latest), suite tuples and tests with check, list_objects and list_users assertions. Returns per-test results and relation coverage. The store tuples are never read.
      # `POST /v1/fga/stores/{id}/tests` (scope: fga:read)
      # @return [Hash]
      def create_test(id, model_id: UNSET, dsl: UNSET, modules: UNSET, tuples: UNSET, tests: UNSET, idempotency_key: nil)
        body = G.compact("model_id" => model_id, "dsl" => dsl, "modules" => modules, "tuples" => tuples, "tests" => tests)
        request(method: :post, path: "/v1/fga/stores/#{enc(id)}/tests", body: body, idempotency_key: idempotency_key)
      end

      # Server-sent stream of the store tuple changes after `since` (or `Last-Event-ID`). Ends after about a minute; reconnect with the last event id.
      # `GET /v1/fga/stores/{id}/watch` (scope: fga:read)
      # @return [Hash]
      def get_watch(id, since: UNSET, type: UNSET)
        query = G.compact("since" => since, "type" => type)
        request(method: :get, path: "/v1/fga/stores/#{enc(id)}/watch", query: query)
      end

      # The managed FGA sync: its settings, how many tuples it owns by kind, the backfill in flight and the last run. Needs an API key that is not limited to organizations.
      # `GET /v1/fga/sync` (scope: fga:read)
      # @return [Atlas::Models::FgaSync]
      def get_sync()
        G.wrap(M::FgaSync, request(method: :get, path: "/v1/fga/sync"))
      end

      # Configure the managed sync that turns organization memberships, org roles and groups into FGA tuples, so a model can say `viewer: member from organization` without mirroring anything by hand. Opt-in per instance; nothing is written until `enabled` is true with a `store_id`. Enabling starts from the current end of the change feed and queues a backfill. The sync only ever removes tuples it wrote; a tuple that existed first is left alone. Tuples the store's model has no relation for are skipped and counted. A store or a tuple name cannot change while the sync owns tuples (409): disable it and `POST /v1/fga/sync/purge` first. Emits nothing itself; its writes emit fga.tuple_written and fga.tuple_deleted.
      # `PUT /v1/fga/sync` (scope: fga:write)
      # @return [Atlas::Models::FgaSync]
      def set_sync(enabled: UNSET, store_id: UNSET, sync_memberships: UNSET, sync_org_roles: UNSET, sync_groups: UNSET, user_type: UNSET, org_type: UNSET, group_type: UNSET, member_relation: UNSET, role_relation_prefix: UNSET, group_key: UNSET, idempotency_key: nil)
        body = G.compact("enabled" => enabled, "store_id" => store_id, "sync_memberships" => sync_memberships, "sync_org_roles" => sync_org_roles, "sync_groups" => sync_groups, "user_type" => user_type, "org_type" => org_type, "group_type" => group_type, "member_relation" => member_relation, "role_relation_prefix" => role_relation_prefix, "group_key" => group_key)
        G.wrap(M::FgaSync, request(method: :put, path: "/v1/fga/sync", body: body, idempotency_key: idempotency_key))
      end

      # Queue a backfill: walk every membership, group member and group and write the tuples that are missing, then remove owned tuples whose source is gone. `repair: true` rewrites every desired tuple, healing tuples someone deleted by hand. Resumable and processed by the worker; read the run to follow it. One backfill runs at a time: asking again returns the one in flight (200). Honours Idempotency-Key. Emits fga_sync.completed or fga_sync.failed when it ends.
      # `POST /v1/fga/sync/backfill` (scope: fga:write)
      # @return [Atlas::Models::FgaSyncRun2]
      def backfill_sync(repair: UNSET, idempotency_key: nil)
        body = G.compact("repair" => repair)
        G.wrap(M::FgaSyncRun2, request(method: :post, path: "/v1/fga/sync/backfill", body: body, idempotency_key: idempotency_key))
      end

      # Remove the tuples the sync wrote (never one that existed before it) and forget them. The sync must be disabled (409 otherwise). Send `confirm: true`.
      # `POST /v1/fga/sync/purge` (scope: fga:write)
      # @return [Atlas::Models::FgaSyncPurge]
      def purge_sync(confirm:, idempotency_key: nil)
        body = G.compact("confirm" => confirm)
        G.wrap(M::FgaSyncPurge, request(method: :post, path: "/v1/fga/sync/purge", body: body, idempotency_key: idempotency_key))
      end

      # Sync runs, newest first: backfills, and the incremental passes that changed something.
      # `GET /v1/fga/sync/runs` (scope: fga:read)
      # @return [Page<FgaSyncRun2>]
      def list_runs(limit: UNSET, starting_after: UNSET)
        query = G.compact("limit" => limit, "starting_after" => starting_after)
        G.page(M::FgaSyncRun2, query) { |q| request(method: :get, path: "/v1/fga/sync/runs", query: q) }
      end

      # One sync run with its counts and any error.
      # `GET /v1/fga/sync/runs/{id}` (scope: fga:read)
      # @return [Atlas::Models::FgaSyncRun2]
      def get_run(id)
        G.wrap(M::FgaSyncRun2, request(method: :get, path: "/v1/fga/sync/runs/#{enc(id)}"))
      end

      # Run an FGA test suite with no store: the model comes from `dsl` or `modules`. Returns per-test results and relation coverage. For CI.
      # `POST /v1/fga/tests` (scope: fga:read)
      # @return [Hash]
      def create_test_all(model_id: UNSET, dsl: UNSET, modules: UNSET, tuples: UNSET, tests: UNSET, idempotency_key: nil)
        body = G.compact("model_id" => model_id, "dsl" => dsl, "modules" => modules, "tuples" => tuples, "tests" => tests)
        request(method: :post, path: "/v1/fga/tests", body: body, idempotency_key: idempotency_key)
      end
    end

    # /v1/flows
    module FlowsOperations
      # A journey's A/B experiments, newest first.
      # `GET /v1/flows/{id}/experiments` (scope: actions:read)
      # @return [Page<JourneyExperiment>]
      def list_experiments(id, limit: UNSET, starting_after: UNSET)
        query = G.compact("limit" => limit, "starting_after" => starting_after)
        G.page(M::JourneyExperiment, query) { |q| request(method: :get, path: "/v1/flows/#{enc(id)}/experiments", query: q) }
      end

      # Create a draft A/B experiment on a journey. Each variant runs one saved version of the journey (the first variant is the control); weights are whole percents adding up to 100. Nothing changes for users until it is started. → 201.
      # `POST /v1/flows/{id}/experiments` (scope: actions:write)
      # @return [Atlas::Models::JourneyExperiment]
      def create_experiment(id, name:, variants:, hypothesis: UNSET, idempotency_key: nil)
        body = G.compact("name" => name, "hypothesis" => hypothesis, "variants" => variants)
        G.wrap(M::JourneyExperiment, request(method: :post, path: "/v1/flows/#{enc(id)}/experiments", body: body, idempotency_key: idempotency_key))
      end

      # Get one journey experiment with its variants and results.
      # `GET /v1/flows/{id}/experiments/{experimentId}` (scope: actions:read)
      # @return [Atlas::Models::JourneyExperiment]
      def get_experiment(id, experiment_id)
        G.wrap(M::JourneyExperiment, request(method: :get, path: "/v1/flows/#{enc(id)}/experiments/#{enc(experiment_id)}"))
      end

      # Change a draft experiment (name, hypothesis, variants). A started experiment keeps its variants so nobody is moved: 409.
      # `PATCH /v1/flows/{id}/experiments/{experimentId}` (scope: actions:write)
      # @return [Atlas::Models::JourneyExperiment]
      def update_experiment(id, experiment_id, name: UNSET, hypothesis: UNSET, variants: UNSET, idempotency_key: nil)
        body = G.compact("name" => name, "hypothesis" => hypothesis, "variants" => variants)
        G.wrap(M::JourneyExperiment, request(method: :patch, path: "/v1/flows/#{enc(id)}/experiments/#{enc(experiment_id)}", body: body, idempotency_key: idempotency_key))
      end

      # Delete a draft or stopped experiment and its assignments. Stop a running one first.
      # `DELETE /v1/flows/{id}/experiments/{experimentId}` (scope: actions:write)
      # @return [nil]
      def delete_experiment(id, experiment_id, idempotency_key: nil)
        request(method: :delete, path: "/v1/flows/#{enc(id)}/experiments/#{enc(experiment_id)}", idempotency_key: idempotency_key)
      end

      # Results per variant. Users are counted from when they were assigned: assigned (reached the journey), started (a run began, meaning the journey held them), completed, abandoned, in progress, completion and abandon rates, the 95% interval of the completion rate, average time to complete, and against the first variant the relative lift and a two-sided p-value (two-proportion z-test) with significant at 0.05. A difference is only worth acting on when significant is true and the sample is large enough.
      # `GET /v1/flows/{id}/experiments/{experimentId}/readout` (scope: actions:read)
      # @return [Atlas::Models::JourneyExperimentReadout]
      def get_readout(id, experiment_id)
        G.wrap(M::JourneyExperimentReadout, request(method: :get, path: "/v1/flows/#{enc(id)}/experiments/#{enc(experiment_id)}/readout"))
      end

      # Start a draft experiment. From now on each user who reaches the journey gets a variant (by weight, from a hash of the experiment and the user, stored on first use so it never changes) and runs that variant's version. One experiment runs per journey at a time (409); the journey must be enabled with an active version. Sends journey.experiment_started. Audited.
